update public.schools set essay_req='자체 supplemental essay 없음. Common App 개인 에세이(프롬프트 중 택1, 250~650단어)만 필수. 일부 장학 프로그램(예: Morrill 등) 별도 지원 시에만 추가 에세이.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://undergrad.osu.edu/apply/freshmen-columbus/apply-step-by-step' where id=41;
update public.schools set essay_req='필수 supplement 1개(300단어 이내): "What about being a student at BU most excites you?" 단일 프롬프트(선택지 없음). Common App 개인 에세이는 별도 필수.', essay_change='2025-26엔 2개 프롬프트(사회·커뮤니티 이슈 성찰 / BU에서 기대되는 것+기여) 중 택1(300단어)이었으나 2026-27부터 단일 프롬프트로 통합되고 ''기여'' 파트가 삭제됨.', essay_cycle='2026-27', essay_source_url='https://www.bu.edu/admissions/apply/first-year/' where id=42;
update public.schools set essay_req='에세이 1개 필수(Common App 개인 에세이 650단어 또는 Rutgers 자체 지원서 3,800자). Rutgers 전용 supplemental essay는 없음. Honors College 희망 시 짧은 진술, Mason Gross 예술 전공은 별도 실기 지원서.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.rutgers.edu/apply/first-year-applicants' where id=43;
update public.schools set essay_req='본 에세이 1개 필수(7개 프롬프트 중 택1, 최대 650단어) + 원서 내 ''문장 완성형'' 단답 6개 필수(각 650자·공백 포함, 약 100단어). 단답 6개는 2025-26과 동일 유지(공식 에세이 페이지에는 본 에세이만 게시, 단답은 원서 내 제시).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.umd.edu/apply/essay-questions' where id=44;
update public.schools set essay_req='Common App로 지원, Common App 개인 에세이(250~650단어)만 필수. UW 전용 필수 단문 없음. 선택 항목: Common App ''Challenges and Circumstances''(250단어), ''Additional Information''(300단어).', essay_change='직전 사이클까지는 UW 지정 프롬프트 에세이(650단어)+필수 커뮤니티/다양성 단문(300단어) 체계였으나, 2026-27 공식 안내 기준 표준 Common App 에세이만 필수로 전환되고 UW 전용 필수 단문이 폐지됨.', essay_cycle='2026-27', essay_source_url='https://admit.washington.edu/apply/first-year/how-to-apply/writing-section/' where id=45;
update public.schools set essay_req='supplemental essay 없음. Common App/Coalition 개인 에세이만 필수. 예외: 예술·미디어·디자인(CAMD) 계열은 포트폴리오(권장) 제출 시 500단어 진술 포함.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.northeastern.edu/application-information/required-materials/' where id=47;
update public.schools set essay_req='Common App 개인 에세이 + Purdue 전용 필수 단문 2개(각 250단어 이내): ① Purdue의 기회가 교내외 관심사를 어떻게 뒷받침할지 ② 전공·캠퍼스(West Lafayette/Indianapolis) 선택 이유. 대체 전공 기재 시 동일 질문 1개 추가. Honors College 지원 시 추가 에세이(각 200단어).', essay_change='최근 두 사이클 내 변경: 필수 단문 2개의 단어 제한이 각 100단어에서 250단어로 확대됨(2025-26부터 적용, 2026-27 동일 유지).', essay_cycle='2026-27', essay_source_url='https://admissions.purdue.edu/apply/essay.php' where id=48;
update public.schools set essay_req='UGA 전용 supplemental essay 없음. Common App 개인 에세이(250~650단어) 1개만 필수.', essay_change='Fall 2026(2025-26 사이클)까지 요구하던 UGA 전용 단문 에세이(200~300단어)를 Fall 2027(2026-27 사이클)부터 폐지 — 공식 입학처 블로그에서 ''개인 에세이 하나로 충분하다''고 명시.', essay_cycle='2026-27', essay_source_url='https://admissions.uga.edu/blog/fall-2027-essay-questions/' where id=49;
update public.schools set essay_req='필수 supplement 1개(최대 250단어): 호기심·창의성이 만나는 로체스터에서 학업 유연성과 비교과 기회를 어떻게 조합할지 묻는 단일 프롬프트. 구조(1개 필수·250단어)는 전 사이클과 동일하고 프롬프트 문구만 교체. Combined Degree·연구 관심 표시 시 추가 단문 있음. AI 작성 지양 명시.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.rochester.edu/applying/how-to-apply/' where id=50;
update public.schools set essay_req='일반 지원자 supplemental essay 없음 — Common App 개인 에세이만 필수. 예외: Pre-Professional Scholars Program(의·치) 지원 시 추가 에세이 2개, 음악 전공은 Arts Supplement.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://case.edu/admission/apply/first-year-applicants' where id=51;
update public.schools set essay_req='supplemental essay 없음. 에세이 1개 필수(Common App 개인 에세이 프롬프트, 최대 650단어) — 원서 제출 후 Admissions Portal에 업로드 가능.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.fsu.edu/first-year/apply' where id=52;
update public.schools set essay_req='ApplyTexas 또는 Common App로 지원. 필수 에세이 1개 — Topic A "Tell us your story..."(고교 시절 자신을 형성한 기회·도전). 추가로 원서 내 필수 단답 수 개(대학 성공을 준비시킨 경험, A&M 지원 이유, 학부 이후 교육 계획, 기타 학업 기록에 영향 준 경험 등). 단어 제한은 플랫폼별 상이(ApplyTexas 기준 자수 제한).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.tamu.edu/apply/freshman/index.html' where id=53;
update public.schools set essay_req='Common App 개인 에세이는 요구하지 않음. 대신 전원 필수인 Ut Prosim Profile 단답 4개(각 120단어): 커뮤니티 기여, 포용·배제 경험, 리더십·자부심 경험 등. 제출 후 수정 불가. 공식 페이지가 ''2026-2027 Short Answer Questions''로 게시 — 4문항·120단어 체계는 전 사이클과 동일.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.vt.edu/admissions/undergraduate/apply/ut-prosim-short-answer-questions.html' where id=54;
update public.schools set essay_req='필수: "Why Wake?"(최대 100단어, supplement 섹션). 추가 단답은 4개 프롬프트(흥미로웠던 책 5권 목록 / 지적 호기심 / 마야 앤절루 인용 응답 / 자유 주제 Top 10 리스트) 중 최대 1개만 선택 응답. 글 또는 영상으로 ''목소리 공유''는 완전 선택(비필수 명시).', essay_change='2026-27부터 단답 프롬프트를 복수 응답하던 방식에서 4개 중 1개 선택으로 축소되고, Why Wake?(100단어)가 supplement 질문 섹션으로 이동 — 공식 입학처 블로그(2026.7)에서 변경 공지.', essay_cycle='2026-27', essay_source_url='https://admissions.wfu.edu/2026/07/wake-forest-applications-open-august-1-heres-whats-new/' where id=55;
update public.schools set essay_req='필수 supplemental essay 없음. 선택 단문 6개 프롬프트(중요한 커뮤니티, 학업 관심·진로, 가족·배경, W&M 관심 계기, 겪은 도전, 우리 동네 투어 등) 중 최대 2개까지 제출 가능(각 약 300단어). 학교는 최대 2개 제출을 강력 권장.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.wm.edu/admission/undergraduateadmission/how-to-apply/first-year-applicants/application-checklist/' where id=56;
update public.schools set essay_req='Common App 미사용 — UC 지원서 단일 체계. 에세이 대신 Personal Insight Questions: 8개 중 4개 선택, 각 최대 350단어. 8개 프롬프트·구조 모두 전 사이클과 동일(UC 전 캠퍼스 공통, 캠퍼스별 추가 에세이 없음).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=57;
update public.schools set essay_req='필수 writing supplement 1개: 5개 프롬프트(형평·정의 옹호 경험 / 나누고 싶은 인생 교훈 / ''new home'' Villanova인 이유 / 정체성으로 오해받은 경험 / 누군가 내 힘을 빌린 순간) 중 택1, 약 250단어. Common App/Coalition 본 에세이와 다른 내용이어야 함. 공식 페이지에 2026-2027 사이클 명시, AI 무단 사용 시 불이익 경고.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.villanova.edu/university/undergraduate-admission/applying-to-villanova/application-essays.html' where id=58;
update public.schools set essay_req='학교별 supplemental essay 필수 아님. 선택(optional) Writing Supplement 1개를 Common App에서 제출 가능 — 공식 지원 단계에 ''Submit a Writing Supplement (Optional on Common App)''로 명시, 미제출 불이익 없음(단어수는 공식 페이지에 미표기). Common App 개인 에세이는 제출.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://undergraduate.admissions.gwu.edu/first-year-applicants' where id=59;
update public.schools set essay_req='Supplemental essay 없음. Personal Statement 자체가 선택(optional) — 공식 페이지에 ''the optional Activities section and Personal Statement''로 명시. Common App으로 지원하면 Common App 에세이가 Penn State Personal Statement로 그대로 인정됨. (Schreyer Honors College 지원자만 별도 에세이 있음.)', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.psu.edu/resources/first-year-students/steps-to-apply' where id=60;
update public.schools set essay_req='선택(optional) supplemental essay 1개, 150-300단어 — ''SCU 교육이 내가 중요하게 여기는 문제(지역/글로벌)를 다루는 데 어떻게 도움이 될지'' 프롬프트. SCU 지원 포털에서 언제든 제출 가능하며 필수 아님.', essay_change='2025-26의 필수 supplemental essay가 폐지되고 2026-27부터 선택 에세이 1개(150-300단어)로 축소됨.', essay_cycle='2026-27', essay_source_url='https://www.scu.edu/admission/undergraduate/first-year-students/' where id=61;
update public.schools set essay_req='학교별 supplemental essay 없음. 자유 주제 에세이(Common App/SUNY 앱 에세이)는 필수. 단 Honors College·WISE·University Scholars는 약 250단어 프로그램 적합성 진술, Scholars for Medicine/Dental Medicine은 650단어 이하 추가 에세이, Creative Writing 전공은 writing sample 필요.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.stonybrook.edu/undergraduate-admissions/apply/first-year.php' where id=62;
update public.schools set essay_req='에세이 필수 아님 — supplemental essay 없음. 공식 체크리스트 기준 지원서·전형료·자기보고 성적(self-reported academic record)만 필수이고, Common App 공식 안내에도 ''No essays, letters of recommendation, ACT/SAT scores, or official transcripts are required to apply''로 명시. 지원서 내 짧은 응답 문항은 선택 제출로 심사·장학금 참고용.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.tc.umn.edu/apply/application-checklist/application-checklist-freshman' where id=63;
update public.schools set essay_req='개인 에세이(250-650단어) + 필수 supplemental 2편 — ①Why Davidson(250-300단어) ②흥미를 느끼는 주제·활동·아이디어(250-300단어).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.davidson.edu/admission-and-financial-aid/apply/first-year-applicants' where id=74;
update public.schools set essay_req='필수 supplement 없음 — Common App 에세이만 (''no required supplement'' 공식 명시). 원하면 추가 자료(글 샘플·에세이 등)를 제출 후 포털에서 첨부 가능.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.grinnell.edu/admission/apply/first-year/requirements' where id=75;
update public.schools set essay_req='필수 supplement 없음 — 선택형 supplemental short answer 1개(모든 플랫폼 또는 제출 후 지원자 포털에서 작성 가능) + Hamilton Hello 영상·개인 URL 등 선택 자료.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.hamilton.edu/admission/apply/details' where id=76;
update public.schools set essay_req='Supplement 없음 — ''supplemental essay를 요구하지 않음'' 공식 명시, Common App/Coalition 개인 에세이만 제출 (예술 포트폴리오는 선택, SlideRoom).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.middlebury.edu/college/admissions/application-instructions-and-deadlines' where id=77;
update public.schools set essay_req='Supplement 없음 — Common App/Coalition 에세이 1편만 제출(자체 보충 문항 폐지 상태 유지, 예술 supplement는 선택).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.smith.edu/admission-aid/apply-smith/first-year-applicants' where id=78;
update public.schools set essay_req='Supplement 없음 — Common App/Coalition 개인 에세이만, 학교별 추가 에세이 없음 (선택형 포트폴리오·보충 자료 제출만 가능).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.wesleyan.edu/admission/application-process.html' where id=80;
update public.schools set essay_req='필수 supplement 없음 — 선택형 short-answer 진술(지원자 포털에서 짧은 에세이 프롬프트에 글 또는 2분 영상으로 응답). Johnson Scholarship 지원 시에만 800단어 이내 에세이 1편 필수(2026-12-01 마감).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.wlu.edu/admissions/apply' where id=81;
update public.schools set essay_req='필수 supplement 없음 — 선택형 supplemental 프롬프트(각 250단어 이내, 예: 다양한 구성원과의 교류에서 얻는 것·나를 고무시키는 것). ''미제출 시 불이익 없음'' 공식 명시.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.colgate.edu/admission-aid/apply' where id=82;
update public.schools set essay_req='필수 supplement 1편 — Richmond Question(제시된 프롬프트 중 택1, 최대 650단어). 구성(1편 필수·650단어)은 유지되며 프롬프트 문구만 매년 갱신 — 2026-27 프롬프트 공식 공개됨.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.richmond.edu/process/materials/index.html' where id=83;
update public.schools set essay_req='Supplement 없음 — Common App 개인 에세이만, 공식 체크리스트에 추가 에세이 항목 없음 (예술·창작 supplement는 선택, 2017-18 사이클부터 supplement 폐지 상태 유지).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://bates.edu/admission/apply/application-checklist' where id=84;
update public.schools set essay_req='Supplemental essay 없음 — Common App/Coalition/QuestBridge 개인 에세이 외 추가 작문 요구 없음. 선택 자료로 Arts Supplement·InitialView 등만 제출 가능', essay_change=null, essay_cycle='2026-27', essay_source_url='https://afa.colby.edu/apply/requirements/' where id=85;
update public.schools set essay_req='필수 supplement 2개 — ① 지적 호기심을 자극하는 주제와 Haverford에서의 탐구 계획(150-200단어) ② Honor Code로 대표되는 커뮤니티 가치와 본인이 찾는 가치(150-200단어)', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.haverford.edu/admission/supplement' where id=86;
update public.schools set essay_req='자체 supplemental essay 없음 — 공식 지원 체크리스트(지원서·성적표·추천서 2부·지원비)에 추가 에세이 항목 없음. 특기 증빙 등 supplementary materials만 선택 제출 가능', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.holycross.edu/admissions-aid/how-to-apply' where id=87;
update public.schools set essay_req='선택(optional) 에세이 2개 — Common App 멤버 섹션에서 ① Twin Cities 입지가 학업·사회·커뮤니티 경험에 주는 이점 ② 4대 가치(학문적 탁월·국제주의·다문화·사회 기여)와 본인의 연결. 둘 다 필수 아님', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.macalester.edu/admissions/us-admissions/first-year/' where id=88;
update public.schools set essay_req='선택(optional) writing supplement 1개 — 공식 지원 절차 페이지에 ''Mount Holyoke writing supplement (optional)''로 명시. Common App/Coalition 개인 에세이는 별도 필수', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.mtholyoke.edu/admission/apply-undergraduate-first-year/application-process' where id=89;
update public.schools set essay_req='필수 writing supplement 1편 (250-500단어, Common App 제출) — ''Bryn Mawr students bring their authentic selves to campus...'' 프롬프트. 공식 페이지는 조사 시점에 2025-26 표기(프롬프트는 2024-25부터 동일)', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.brynmawr.edu/admissions-aid/apply/first-year-students' where id=90;
update public.schools set essay_req='장문형 supplemental essay 없음 — 자체 문항은 1개뿐: 1지망 전공(또는 undecided)·2지망 전공 선택 이유를 250단어 이내로 설명하는 short answer', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.bucknell.edu/admissions-aid/admissions-blog/tips-writing-college-application-essay' where id=91;
update public.schools set essay_req='선택(optional) supplemental essay 1편 (최대 300단어) — Block Plan식 ''한 가지에 깊이 몰입한 경험'' 프롬프트. 공식 페이지(2026-27 명시)에 ''미제출해도 불이익 없음'' 안내', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.coloradocollege.edu/admission/for-students/admission-requirements/supplemental-essay.html' where id=92;
update public.schools set essay_req='선택(optional) ''Why Lafayette?'' 에세이 1편 (20-200단어) — Common App 멤버 페이지 내, 필수 아님', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.lafayette.edu/apply/' where id=93;
update public.schools set essay_req='Supplemental essay 없음 — 공식 지원 페이지에 ''No Supplemental Essay Required'' 명시. Common App/Coalition 개인 에세이만 제출', essay_change=null, essay_cycle='2026-27', essay_source_url='https://denison.edu/campus/admission/apply-for-admission' where id=94;
update public.schools set essay_req='Supplemental essay 없음 — 공식 지원 체크리스트에 추가 에세이 항목 없음. 포트폴리오 등 supplemental materials만 선택 제출 가능', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.fandm.edu/apply/regular-decision-application-checklist.html' where id=95;
update public.schools set essay_req='선택(optional) short answer 1개 (최대 250단어) — ''Why Occidental / 왜 Oxy가 맞는 곳인가'' 프롬프트. 공식 체크리스트(Fall 2027 입학 = 2026-27 사이클)에 ''not mandatory'' 명시', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.oxy.edu/admission-aid/first-year/application-requirements' where id=96;
update public.schools set essay_req='필수 writing supplement 1편 (최대 650단어) — 2개 프롬프트(① 핵심가치 5개 중 하나와의 참여 경험 ② 원하는 대학 경험과 Pitzer 핏) 중 택1', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.pitzer.edu/admission-aid/how-apply/first-year-applicants' where id=97;
update public.schools set essay_req='별도 supplemental essay 없음 — 에세이 1개만 필수. Apply IU로 지원 시 IU 지정 프롬프트(200-400단어, 학업·진로 계획과 IU에서 하고 싶은 활동), Common App으로 지원 시 Common App 에세이 프롬프트 중 하나로 대체 가능.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://bloomington.iu.edu/admissions/apply/application-faqs.html' where id=99;
update public.schools set essay_req='MSU 자체 supplemental essay 없음. 에세이 1개는 필수(250-650단어) — 7개 프롬프트(자유 주제 포함) 중 선택하며 Common App 개인 에세이에 해당. 합격 가능성 제고 및 장학금 심사에 활용.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.msu.edu/apply/first-year/how-to-apply' where id=100;
update public.schools set essay_req='Common App/Coalition 에세이(650단어 이하) 필수 + NC State 단답 1개 필수 — ''위에서 선택한 전공(들)을 고른 이유와 왜 NC State에서 공부하고 싶은지''(공식 페이지에 단어수 미표기, 안내 기준 최대 250단어). University Honors Program 지원 희망자는 600단어 이하 에세이(선택, 11/1 마감, Park Scholarships와 동일 프롬프트) 추가.', essay_change='2지망 전공 이유를 묻던 두 번째 단답이 사라지고 전공 선택 이유 단답 1개로 정리됨.', essay_cycle='2026-27', essay_source_url='https://admissions.ncsu.edu/apply/first-year/' where id=101;
update public.schools set essay_req='일반 지원자용 supplemental essay 없음 — 지원서의 general essay/personal statement로 에세이 요건 충족(''satisfies our requirements''). 단 Architecture, Electronic Arts, Games and Simulation Arts and Sciences, Music, Physician-Scientist(B.S./M.D.) 지원자는 프로그램별 에세이(Common App writing supplement)를 필수 제출.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://undergrad.admissions.rpi.edu/apply' where id=102;
update public.schools set essay_req='Supplemental essay 없음 — 공식 발표: ''The University of Miami does not require a supplemental essay for first-year admission as of the 2026-2027 application cycle.'' Common App 개인 에세이만 제출(필수). Frost School of Music 등 일부 프로그램은 별도 지원 자료(오디션 등) 필요.', essay_change='2026-27부터 마이애미 자체 supplemental essay 문항이 폐지되어 Common App 개인 에세이만 제출하면 됨.', essay_cycle='2026-27', essay_source_url='https://news.miami.edu/admissions/stories/2026/07/does-the-university-of-miami-require-a-supplemental-essay.html' where id=104;
update public.schools set essay_req='Supplemental essay 없음 — 공식 지원 안내(Application Instructions)의 제출 항목은 지원서(활동 목록·personal statement 포함), 성적표, 추천서, 선택 시험 점수뿐이며 ''Why Tulane'' 등 추가 에세이 항목이 없음. Common App 개인 에세이(personal statement)는 필수.', essay_change='선택(optional)이던 ''Why Tulane'' supplemental essay가 2026-27 사이클부터 중단(폐지)되어 개인 에세이만 제출함.', essay_cycle='2026-27', essay_source_url='https://admission.tulane.edu/apply/instructions' where id=106;
update public.schools set essay_req='Supplemental essay 없음. Common App/Coalition 개인 에세이는 필수(250-650단어 권장 범위) — ''The personal essay is required''로 공식 명시. 단 간호학과(DeLuca School of Nursing) 지원자만 간호 동기 관련 추가 문항 1개 응답.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.uconn.edu/apply/first-year/instructions/' where id=107;
update public.schools set essay_req='Supplemental essay 없음. 에세이는 지원(admission) 자체에 필수 아님 — 공식 요구 서류는 지원서·전형료·STARS(자기보고 성적)·선택 시험 점수뿐. 단 personal statement는 장학금 심사 대상이 되려면 필요(''required to be considered for scholarships'')하므로 사실상 제출 권장. Frederick Honors College는 별도 검토.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.pitt.edu/first-year-student/' where id=108;
update public.schools set essay_req='Supplement 없음. Common App/SUNY App/Coalition 지원서의 본 에세이 외 학교 자체 supplemental essay를 요구하지 않음 (공식 체크리스트에 에세이 항목 없음).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.binghamton.edu/admissions/undergraduate/apply/freshman/' where id=109;
update public.schools set essay_req='Supplement 없음. 에세이 자체가 입학 필수 요건이 아니며, personal statement 등 추가 자료는 전부 선택 제출 (''Clemson does not require any of these additional materials for admission'').', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.clemson.edu/admissions/undergraduate-admissions/apply/first-year.html' where id=110;
update public.schools set essay_req='Supplement 없음. 본 에세이 1개 필수 — Rutgers 자체 지원서는 3,800자(공백 포함), Common App은 650단어 이내. Common App 경로는 supplemental essay 없음을 공식 명시, Honors 지원 시에만 short statement 추가.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.rutgers.edu/apply/first-year-applicants' where id=111;
update public.schools set essay_req='Supplement 없음. 공식 체크리스트에 writing supplement 항목 없음(Common App 본 에세이만). 단 Architecture·Visual and Performing Arts는 포트폴리오/오디션 등 단과대별 추가 자료 요구.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.syracuse.edu/admissions-aid/application-process/undergraduate/first-year/application-checklist/' where id=112;
update public.schools set essay_req='Supplement 없음. Common App/Coalition 본 에세이 외 학교 자체 supplemental essay 요구 없음 (공식 요건: 성적표·전공 선택, 추천서·시험점수는 선택).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.buffalo.edu/admissions/apply/first-year.html' where id=113;
update public.schools set essay_req='UC 공통 지원서 Personal Insight Questions: 8개 중 4개 선택 응답, 각 350단어 이내. 캠퍼스 자체 추가 에세이 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-first-year/personal-insight-questions.html' where id=114;
update public.schools set essay_req='Supplement 없음. 에세이는 필수가 아닌 선택 제출 자료 (holistic review에서 선택 자료로만 고려).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.mines.edu/undergraduate-admissions/first-year/' where id=115;
update public.schools set essay_req='Supplement 없음. Common App/Coalition(Scoir) 본 에세이 250–650단어 1개 필수, Drexel 자체 supplemental essay 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://drexel.edu/admissions/apply/undergrad-instructions/first-year-instructions' where id=116;
update public.schools set essay_req='Supplement 없음. Common App 본 에세이만 평가에 사용, NJIT 자체 supplemental essay 요구 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.njit.edu/admissions/how-we-evaluate-applicants' where id=117;
update public.schools set essay_req='Supplement 없음. 지원서에 포함된 본 에세이(''Essay — included on your application'') 1개 필수, Stevens 자체 supplemental essay 없음. Music·Visual Arts & Technology 지원자는 포트폴리오 강력 권장.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.stevens.edu/admission-aid/undergraduate-admissions/first-year-students' where id=118;
update public.schools set essay_req='필수 supplement 1개: 기독교 대학인 Pepperdine에 지원하는 이유와 캠퍼스 내 신앙 대화에 어떻게 기여할지(300–500단어). Common App 본 에세이에 추가로 제출.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.pepperdine.edu/apply/undergraduate/first-year-applicants.htm' where id=119;
update public.schools set essay_req='Common App 본 에세이 필수 + UIC Member Profile의 짧은 에세이(희망 전공 또는 관심 진로 분야에 관해) 1개 필수. 단어수는 공식 페이지에 미표기.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.uic.edu/application-tips' where id=120;
update public.schools set essay_req='Supplement 없음. 공식 지원 요건(Common App·성적표·추천서)에 WPI 자체 supplemental essay 항목 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.wpi.edu/admissions/undergraduate/apply/how-to' where id=121;
update public.schools set essay_req='자체 지원서 기준: 본 에세이 1개(7개 프롬프트 중 선택) + Personal Statement 1개 필수(''YU가 학업 목표를 지원하며 개인·가치 성장에 어떻게 도움이 될지'', 최대 250단어). 인터뷰 전원 필수. 공식 페이지는 ''Spring 2027 admissions and beyond'' 기준 프롬프트 표기.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://apply.yu.edu/freshman' where id=122;
update public.schools set essay_req='선택(optional) supplement 1개: ''American University students identify as changemakers... Describe a belief, hobby, idea, issue, or topic about which you''re excited'' (2026-2027 사이클 명시, 단어수는 체크리스트 페이지에 미표기). 본 에세이는 필수.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.american.edu/admissions/first-year/checklist.cfm' where id=123;
update public.schools set essay_req='본 에세이 1개 필수(goBAYLOR 또는 Common App). Short Answer Response(''Why Baylor·기여'', 약 450단어)는 11/1 Early Decision(binding) 지원자만 필수, 그 외 지원자는 권장(선택) 제출.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.web.baylor.edu/admissions/incoming-freshman/application-process' where id=124;
update public.schools set essay_req='Common App 본 에세이 필수 + 선택(optional) essay 1개(Common App Writing 섹션에서 접근, 제출 의무 없음).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.howard.edu/undergraduate/first-year' where id=125;
update public.schools set essay_req='Supplement 없음. 본 에세이(personal statement) 1개 필수(Common App 또는 Marquette 자체 지원서). 추가 personal statement·추천서는 필수 아님(제출 시 검토만).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.marquette.edu/admissions/undergraduate/first-year-application.php' where id=126;
update public.schools set essay_req='Supplement 없음. Common App/RIT 지원서 본 에세이 1개 필수. 단 Honors Program·Individualized Program BS 지원 시에만 supplemental essay 1개 추가 필수.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.rit.edu/admissions/first-year-application' where id=127;
update public.schools set essay_req='필수 supplement 없음. 지원 플랫폼(Common App·ApplyTexas·SMU 자체·Coalition) 본 에세이 250–650단어 필수, 공식 요건 페이지에 SMU 자체 필수 supplemental essay 항목 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.smu.edu/admission/apply/undergraduate-admission/requirements-guidelines' where id=128;
update public.schools set essay_req='UC 공통 지원서 Personal Insight Questions: 8개 중 4개 선택 응답, 각 350단어 이내. 캠퍼스 자체 추가 에세이 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-first-year/personal-insight-questions.html' where id=129;
update public.schools set essay_req='Supplement 없음 — Common App/Coalition 개인 에세이(필수)만 제출, 별도 추가 에세이 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.udel.edu/apply/undergraduate-admissions/first-year-students/admissions-requirements/' where id=130;
update public.schools set essay_req='에세이 없음 — 원서(자체 또는 Common App)+수수료+SSAR 성적 자가보고+시험점수만 요구, 개인 에세이·supplement 모두 없음 (Judy Genshaft Honors College 지원 시에만 별도 지원서).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.usf.edu/admissions/freshmen/admission-information/how-to-apply.aspx' where id=131;
update public.schools set essay_req='에세이 없음 — Common App 원서·시험점수(SAT/ACT/CLT)·성적표만 요구, 개인 에세이·supplement 없음 (Honors College 지원 시에만 personal statement).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.fiu.edu/how-to-apply/freshman-applicant/' where id=132;
update public.schools set essay_req='필수 supplement 없음 — Common App 에세이(필수) + 선택형 short responses 3종(Unique Fordham question·Additional information·Challenges and circumstances). 2026-27 마감일 기준 공식 페이지에서 ''Optional application components''로 명시.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.fordham.edu/undergraduate-admission/apply/' where id=133;
update public.schools set essay_req='Supplement 없음 — Rutgers 자체 원서는 에세이 1편 필수(3,800자 이내, 프롬프트 7개 중 택1 또는 자유 주제), Common App은 개인 에세이(250-650단어)만. ''Common App 지원 시 supplemental essay 없음'' 공식 명시 (Honors 고려 시 짧은 진술만 추가).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.rutgers.edu/apply/first-year-applicants' where id=134;
update public.schools set essay_req='에세이 1편 필수(300-500단어) — TCU 자체 원서는 4개 프롬프트 중 택1, Common App·Coalition·ApplyTexas는 해당 플랫폼 에세이 사용(별도 TCU supplement 없음). 선택형 ''Freedom of Expression'' 제출물(에세이·시·작품·URL) 권장.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.tcu.edu/apply/first-year/index.php' where id=135;
update public.schools set essay_req='Common App 개인 에세이(250-650단어) + 필수 supplemental short answer 1개(250단어, ''CU Boulder에서 무엇을 왜 공부하고 싶은가'' — 개인 에세이와 다른 내용이어야 함). 에세이 미제출 시 심사 불가 명시. 2026-27 사이클 페이지에서 확인.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.colorado.edu/admissions/process/first-year/apply' where id=136;
